-- ============================================================================
-- NAFUME — Cloudflare D1 (SQLite) schema
-- ----------------------------------------------------------------------------
-- Equivalent of db/schema.sql (Postgres) including every migration in
-- db/migrations/, for a NEW, EMPTY D1 database:
--
--   npx wrangler d1 execute nafume --remote --file db/d1/schema.sql
--
-- Type mapping used by server/_lib/db-d1.js:
--   UUID / TIMESTAMPTZ -> TEXT   (ids are generated by the app; timestamps are
--                                 ISO-8601 UTC strings, which sort correctly)
--   BOOLEAN            -> INTEGER 0/1   (the driver converts to true/false)
--   JSONB              -> TEXT          (the driver stringifies / parses)
--
-- SECURITY MODEL
--   D1 has no public endpoint. It is reachable only through the Worker's `DB`
--   binding, so there is no anon key and no Row Level Security to configure.
--   whatsapp_broadcast_audience is therefore never exposed to the browser.
--
-- Nothing here drops or truncates data; every statement is IF NOT EXISTS.
-- ============================================================================

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS customers (
  id                TEXT PRIMARY KEY,
  name              TEXT,
  email             TEXT,
  email_normalized  TEXT,
  phone             TEXT,
  phone_normalized  TEXT,
  address_line1     TEXT,
  address_line2     TEXT,
  city              TEXT,
  state             TEXT,
  pincode           TEXT,
  country           TEXT    NOT NULL DEFAULT 'India',
  has_account       INTEGER NOT NULL DEFAULT 0,
  source            TEXT    NOT NULL DEFAULT 'checkout',
  email_verified_at TEXT,
  phone_verified_at TEXT,
  created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS customers_email_normalized_key
  ON customers (email_normalized) WHERE email_normalized IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS customers_phone_normalized_key
  ON customers (phone_normalized) WHERE phone_normalized IS NOT NULL;
CREATE INDEX IF NOT EXISTS customers_created_at_idx ON customers (created_at DESC);

CREATE TABLE IF NOT EXISTS customer_auth (
  id              TEXT PRIMARY KEY,
  customer_id     TEXT    NOT NULL UNIQUE REFERENCES customers(id) ON DELETE CASCADE,
  password_hash   TEXT    NOT NULL,
  failed_attempts INTEGER NOT NULL DEFAULT 0,
  locked_until    TEXT,
  created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE IF NOT EXISTS sessions (
  id          TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  token_hash  TEXT NOT NULL UNIQUE,
  method      TEXT NOT NULL DEFAULT 'password',
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  expires_at  TEXT NOT NULL,
  revoked_at  TEXT
);
CREATE INDEX IF NOT EXISTS sessions_customer_idx ON sessions (customer_id);
CREATE INDEX IF NOT EXISTS sessions_expires_idx  ON sessions (expires_at);

CREATE TABLE IF NOT EXISTS orders (
  id                      TEXT PRIMARY KEY,
  order_id                TEXT    NOT NULL UNIQUE,
  customer_id             TEXT    REFERENCES customers(id) ON DELETE SET NULL,

  razorpay_order_id       TEXT,
  razorpay_payment_id     TEXT,
  razorpay_signature      TEXT,

  currency                TEXT    NOT NULL DEFAULT 'INR',
  amount_subtotal         INTEGER NOT NULL DEFAULT 0,
  amount_bundle_discount  INTEGER NOT NULL DEFAULT 0,
  amount_prepaid_discount INTEGER NOT NULL DEFAULT 0,
  amount_gift_addon       INTEGER NOT NULL DEFAULT 0,
  amount_shipping         INTEGER NOT NULL DEFAULT 0,
  discount_code           TEXT,
  amount_discount         INTEGER NOT NULL DEFAULT 0,
  amount_total            INTEGER NOT NULL DEFAULT 0,

  payment_status          TEXT    NOT NULL DEFAULT 'pending'
    CHECK (payment_status IN ('pending','awaiting_verification','paid','failed','refunded')),
  order_status            TEXT    NOT NULL DEFAULT 'created',
  fulfillment_status      TEXT    NOT NULL DEFAULT 'unfulfilled',
  payment_method          TEXT    NOT NULL DEFAULT 'razorpay',
  checkout_type           TEXT    NOT NULL DEFAULT 'razorpay',

  ship_name               TEXT,
  ship_phone              TEXT,
  ship_email              TEXT,
  ship_email_normalized   TEXT,
  ship_line1              TEXT,
  ship_line2              TEXT,
  ship_city               TEXT,
  ship_state              TEXT,
  ship_pincode            TEXT,
  ship_country            TEXT    NOT NULL DEFAULT 'India',

  whatsapp_opt_in         INTEGER NOT NULL DEFAULT 0,
  ga_client_id            TEXT,
  ga_sent_at              TEXT,
  notes                   TEXT,
  offers                  TEXT    NOT NULL DEFAULT '[]',

  shipped_at              TEXT,
  delivered_at            TEXT,
  courier_name            TEXT,
  awb                     TEXT,

  review_request_status   TEXT    NOT NULL DEFAULT 'not_due',
  review_requested_at     TEXT,
  review_id               TEXT,

  placed_by_customer_id      TEXT REFERENCES customers(id) ON DELETE SET NULL,
  verified_owner_customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL,
  pending_payment_id         TEXT,
  payment_captured_amount    INTEGER,
  payment_currency           TEXT,
  payment_confirmed_via      TEXT,
  payment_checked_at         TEXT,
  payment_note               TEXT,

  paid_at                 TEXT,
  created_at              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS orders_razorpay_payment_id_key
  ON orders (razorpay_payment_id) WHERE razorpay_payment_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS orders_razorpay_order_id_key
  ON orders (razorpay_order_id) WHERE razorpay_order_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS orders_customer_idx             ON orders (customer_id);
CREATE INDEX IF NOT EXISTS orders_created_idx              ON orders (created_at DESC);
CREATE INDEX IF NOT EXISTS orders_ship_email_idx           ON orders (ship_email);
CREATE INDEX IF NOT EXISTS orders_ship_phone_idx           ON orders (ship_phone);
CREATE INDEX IF NOT EXISTS orders_delivered_idx            ON orders (delivered_at) WHERE delivered_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS orders_discount_code_idx        ON orders (discount_code) WHERE discount_code IS NOT NULL;
CREATE INDEX IF NOT EXISTS orders_ship_email_normalized_idx ON orders (ship_email_normalized);
CREATE INDEX IF NOT EXISTS orders_verified_owner_idx       ON orders (verified_owner_customer_id);
CREATE INDEX IF NOT EXISTS orders_payment_open_idx         ON orders (payment_status, created_at)
  WHERE payment_status IN ('pending', 'awaiting_verification');

CREATE TABLE IF NOT EXISTS order_items (
  id           TEXT PRIMARY KEY,
  order_uuid   TEXT    NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  order_id     TEXT    NOT NULL,
  product_id   TEXT    NOT NULL,
  product_name TEXT    NOT NULL,
  unit_price   INTEGER NOT NULL,
  quantity     INTEGER NOT NULL,
  line_total   INTEGER NOT NULL,
  created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS order_items_order_idx    ON order_items (order_uuid);
CREATE INDEX IF NOT EXISTS order_items_order_id_idx ON order_items (order_id);

CREATE TABLE IF NOT EXISTS leads (
  id               TEXT PRIMARY KEY,
  email            TEXT NOT NULL,
  email_normalized TEXT NOT NULL,
  source           TEXT NOT NULL,
  discount_code    TEXT,
  discount_label   TEXT,
  metadata         TEXT NOT NULL DEFAULT '{}',
  converted_at     TEXT,
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS leads_email_source_key ON leads (email_normalized, source);
CREATE INDEX IF NOT EXISTS leads_created_idx ON leads (created_at DESC);

CREATE TABLE IF NOT EXISTS marketing_consent (
  id             TEXT PRIMARY KEY,
  customer_id    TEXT    NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  channel        TEXT    NOT NULL,
  opted_in       INTEGER NOT NULL DEFAULT 0,
  consent_source TEXT    NOT NULL,
  consent_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  revoked_at     TEXT,
  updated_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS marketing_consent_customer_channel_key
  ON marketing_consent (customer_id, channel);

CREATE TABLE IF NOT EXISTS quiz_responses (
  id                       TEXT PRIMARY KEY,
  email                    TEXT,
  email_normalized         TEXT,
  customer_id              TEXT REFERENCES customers(id) ON DELETE SET NULL,
  lead_id                  TEXT REFERENCES leads(id) ON DELETE SET NULL,
  answers                  TEXT NOT NULL DEFAULT '{}',
  recommended_product_id   TEXT,
  recommended_product_name TEXT,
  alternate_product_id     TEXT,
  preference_tags          TEXT NOT NULL DEFAULT '[]',
  source                   TEXT NOT NULL DEFAULT 'fragrance_quiz',
  created_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS quiz_email_idx   ON quiz_responses (email_normalized);
CREATE INDEX IF NOT EXISTS quiz_created_idx ON quiz_responses (created_at DESC);

CREATE TABLE IF NOT EXISTS reviews (
  id             TEXT PRIMARY KEY,
  order_id       TEXT,
  order_uuid     TEXT    REFERENCES orders(id) ON DELETE SET NULL,
  customer_id    TEXT    REFERENCES customers(id) ON DELETE SET NULL,
  product_id     TEXT    NOT NULL,
  product_name   TEXT,
  rating         INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  title          TEXT,
  body           TEXT,
  photo_data_url TEXT,
  author_name    TEXT,
  author_email   TEXT,
  verified       INTEGER NOT NULL DEFAULT 0,
  status         TEXT    NOT NULL DEFAULT 'pending',
  access_method  TEXT,
  created_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS reviews_order_product_key
  ON reviews (order_id, product_id) WHERE order_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS reviews_product_idx ON reviews (product_id, status);

CREATE TABLE IF NOT EXISTS review_requests (
  id                      TEXT PRIMARY KEY,
  order_id                TEXT    NOT NULL UNIQUE,
  order_uuid              TEXT    REFERENCES orders(id) ON DELETE CASCADE,
  customer_id             TEXT    REFERENCES customers(id) ON DELETE SET NULL,
  channel                 TEXT    NOT NULL DEFAULT 'email',
  scheduled_for           TEXT    NOT NULL,
  status                  TEXT    NOT NULL DEFAULT 'queued',
  attempts                INTEGER NOT NULL DEFAULT 0,
  last_error              TEXT,
  sent_at                 TEXT,
  access_token_hash       TEXT,
  access_token_expires_at TEXT,
  created_at              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS review_requests_due_idx ON review_requests (status, scheduled_for);
CREATE UNIQUE INDEX IF NOT EXISTS review_requests_access_token_key
  ON review_requests (access_token_hash) WHERE access_token_hash IS NOT NULL;

CREATE TABLE IF NOT EXISTS outbound_messages (
  id                  TEXT PRIMARY KEY,
  channel             TEXT    NOT NULL,
  to_address          TEXT    NOT NULL,
  subject             TEXT,
  body                TEXT,
  status              TEXT    NOT NULL DEFAULT 'queued',
  provider            TEXT,
  provider_message_id TEXT,
  error               TEXT,
  related_type        TEXT,
  related_id          TEXT,
  attempts            INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  sent_at             TEXT
);
CREATE INDEX IF NOT EXISTS outbound_status_idx ON outbound_messages (status, created_at);

CREATE TABLE IF NOT EXISTS discount_redemptions (
  id              TEXT PRIMARY KEY,
  code            TEXT    NOT NULL,
  customer_id     TEXT    REFERENCES customers(id) ON DELETE SET NULL,
  order_id        TEXT    NOT NULL,
  order_uuid      TEXT    REFERENCES orders(id) ON DELETE CASCADE,
  review_id       TEXT    REFERENCES reviews(id) ON DELETE SET NULL,
  subtotal_before INTEGER NOT NULL DEFAULT 0,
  discount_amount INTEGER NOT NULL DEFAULT 0,
  final_amount    INTEGER NOT NULL DEFAULT 0,
  status          TEXT    NOT NULL DEFAULT 'pending',
  allowance_slot  INTEGER,
  slot_key        TEXT,
  created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  redeemed_at     TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS discount_redemptions_code_order_key
  ON discount_redemptions (code, order_id);
CREATE UNIQUE INDEX IF NOT EXISTS discount_redemptions_slot_key
  ON discount_redemptions (slot_key) WHERE slot_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS discount_redemptions_customer_idx ON discount_redemptions (customer_id, code);
CREATE INDEX IF NOT EXISTS discount_redemptions_status_idx   ON discount_redemptions (status, created_at);

CREATE TABLE IF NOT EXISTS rate_limits (
  id           TEXT PRIMARY KEY,
  bucket       TEXT    NOT NULL,
  window_start TEXT    NOT NULL,
  window_end   TEXT    NOT NULL,
  hits         INTEGER NOT NULL DEFAULT 1,
  created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS rate_limits_bucket_window_key ON rate_limits (bucket, window_start);
CREATE INDEX IF NOT EXISTS rate_limits_expiry_idx ON rate_limits (window_end);

CREATE TABLE IF NOT EXISTS verification_challenges (
  id              TEXT PRIMARY KEY,
  purpose         TEXT    NOT NULL,
  channel         TEXT    NOT NULL,
  identifier      TEXT    NOT NULL,
  customer_id     TEXT    REFERENCES customers(id) ON DELETE CASCADE,
  payload         TEXT    NOT NULL DEFAULT '{}',
  code_hash       TEXT,
  provider        TEXT    NOT NULL,
  attempts        INTEGER NOT NULL DEFAULT 0,
  max_attempts    INTEGER NOT NULL DEFAULT 5,
  send_count      INTEGER NOT NULL DEFAULT 1,
  last_sent_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  expires_at      TEXT    NOT NULL,
  consumed_at     TEXT,
  invalidated_at  TEXT,
  live_key        TEXT,
  created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS verification_challenges_live_key
  ON verification_challenges (live_key) WHERE live_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS verification_challenges_identifier_idx
  ON verification_challenges (channel, identifier, created_at DESC);
CREATE INDEX IF NOT EXISTS verification_challenges_expiry_idx
  ON verification_challenges (expires_at);

CREATE TABLE IF NOT EXISTS payment_events (
  id                  TEXT PRIMARY KEY,
  event_key           TEXT    NOT NULL,
  provider            TEXT    NOT NULL DEFAULT 'razorpay',
  event_type          TEXT,
  razorpay_payment_id TEXT,
  razorpay_order_id   TEXT,
  outcome             TEXT,
  received_at         TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  processed_at        TEXT,
  attempts            INTEGER NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS payment_events_event_key ON payment_events (event_key);
CREATE INDEX IF NOT EXISTS payment_events_payment_idx ON payment_events (razorpay_payment_id);

CREATE TABLE IF NOT EXISTS desk_events (
  id         TEXT PRIMARY KEY,
  order_id   TEXT    NOT NULL,
  status     TEXT    NOT NULL DEFAULT 'queued',
  attempts   INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  sent_at    TEXT
);
CREATE INDEX IF NOT EXISTS desk_events_status_idx ON desk_events (status, created_at);
CREATE INDEX IF NOT EXISTS desk_events_order_idx  ON desk_events (order_id);

CREATE TABLE IF NOT EXISTS schema_migrations (
  version    TEXT PRIMARY KEY,
  applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Marketing export view: only opted-in, non-revoked WhatsApp numbers.
CREATE VIEW IF NOT EXISTS whatsapp_broadcast_audience AS
  SELECT c.id AS customer_id, c.name, c.phone, c.phone_normalized,
         mc.consent_at, mc.consent_source
  FROM customers c
  JOIN marketing_consent mc ON mc.customer_id = c.id
  WHERE mc.channel = 'whatsapp'
    AND mc.opted_in = 1
    AND mc.revoked_at IS NULL
    AND c.phone_normalized IS NOT NULL;

INSERT OR IGNORE INTO schema_migrations (version) VALUES
  ('20260915_launch_readiness'),
  ('20261026_desk_events'),
  ('20261022_secure_broadcast_view'),
  ('d1_initial');
